style.css:
@-moz-document domain("google.com") {
/* --- Core Theme: Google Baby Blue Kawaii --- */
    :root {
        --google-blue-bg: #E3F2FD;       
        --google-white-card: #FFFFFF;    
        --google-blue-text: #42A5F5;     
        --google-blue-subtext: #64B5F6;  
        --google-accent: #90CAF9;       
        --kawaii-radius: 24px;           
    }

    /* Apply cute font and baby blue text color globally */
    body, div, span, p, a, input, button {
        font-family: 'Quicksand', 'Nunito', sans-serif !important;
        color: var(--google-blue-text) !important;
    }

    /* Change main Google background */
    body, #gsr, #main, .cnt, #rcnt {
        background-color: var(--google-blue-bg) !important;
        background-image: none !important;
    }

    /* --- [NEW] Turn the Image Logo into a Cute Font Logo --- */
    /* Hides the default Google logo image on the home page */
    .lnXb9c, img[alt="Google"], #logo img, img[src*="logo"] {
        display: none !important;
    }

    /* Replaces the hidden image with a cute custom font text logo */
    .k1zZkc, .logo, #logo, .F1hUFe {
        content: "" !important;
        display: flex !important;
        justify-content: center !important;
        align-items: center !important;
    }

    .k1zZkc::after, .logo::after, #logo::after, .F1hUFe::after {
        content: "google" !important;
        font-family: 'Quicksand', sans-serif !important;
        font-weight: 700 !important;
        font-size: 80px !important; /* Adjust scale for home page */
        color: var(--google-blue-text) !important;
        letter-spacing: -2px !important;
        text-transform: lowercase !important;
        display: block !important;
    }

    /* Adjusts the text logo size so it fits perfectly in the top corner of the search results page */
    #logo::after {
        font-size: 32px !important;
        letter-spacing: -1px !important;
    }

    /* --- Force All Icons into Baby Blue --- */
    svg, g, path, .wvbx7d, .Gdd5U, .QCzoEc, .Xv4xee, [class*="icon"], [class*="Icon"] {
        fill: var(--google-blue-text) !important;
        color: var(--google-blue-text) !important;
        stroke: var(--google-blue-text) !important;
    }

    /* Customize the Search Bar (Rounded, White, Blue Shadow) */
    .gLFyf, .RNNXgb, .sbi_b {
        background-color: var(--google-white-card) !important;
        border: 4px solid #FFFFFF !important;
        border-radius: var(--kawaii-radius) !important;
        box-shadow: 0 4px 12px rgba(144, 202, 249, 0.25) !important;
    }

    /* Customize individual search results into clean white cards */
    .g, .MjjYud, .jkv7Vb, .Ww4FFb, .hlcw0c .g {
        background-color: var(--google-white-card) !important;
        border-radius: var(--kawaii-radius) !important;
        border: 4px solid #FFFFFF !important;
        padding: 16px !important;
        margin-bottom: 16px !important;
        box-shadow: 0 4px 12px rgba(144, 202, 249, 0.15) !important;
    }

    /* Search Result Titles */
    .g h3, .EK1xGf h3, h3.LC20lb {
        color: var(--google-blue-text) !important;
        font-weight: 700 !important;
    }

    /* Search Result Snippet Description Text */
    .VwiC3b, .MUxGbd, .st {
        color: var(--google-blue-subtext) !important;
    }

    /* Navigation tools bar (All, Images, Videos, etc.) */
    .O3S9Cc, .crJ5V, .NFQFxe {
        background-color: rgba(255, 255, 255, 0.8) !important;
        border-radius: var(--kawaii-radius) !important;
        border: 3px solid #FFFFFF !important;
    }

    /* Custom Buttons (Search buttons, page navigation buttons) */
    .gNO89b, .RNmpXc, .lsb, .fl, .Xv4xee {
        background-color: var(--google-accent) !important;
        border: 2px solid #FFFFFF !important;
        color: white !important;
        border-radius: 20px !important;
    }

    .gNO89b:hover, .RNmpXc:hover {
        background-color: #64B5F6 !important;
        box-shadow: 0 2px 8px rgba(144, 202, 249, 0.4) !important;
    }
}
